    /** Destination for receiving YT tokens */
    tokenYtTrader: TAccountMetas[3];
    tokenPtTrader: TAccountMetas[4];
    /** Temporary SY account owned by market */
    tokenSyEscrow: TAccountMetas[5];
    /** PT liquidity owned by market */
