    tokenFeeTreasurySy: TAccountMetas[7];
    tokenProgram: TAccountMetas[8];
    addressLookupTable: TAccountMetas[9];
    syProgram: TAccountMetas[10];
    vaultAuthority: TAccountMetas[11];
    vault: TAccountMetas[12];
    tokenSyEscrowVault: TAccountMetas[13];
    mintYt: TAccountMetas[14];
    mintPt: TAccountMetas[15];
    addressLookupTableVault: TAccountMetas[16];
